class LegacyFilterIteratorFrameTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final String CALLER = "callerGraph";
	private static final String PRIVATE = "privateGraphInput";
	private static final IRI G1 = VF.createIRI("urn:legacy-frame:one");
	private static final IRI G2 = VF.createIRI("urn:legacy-frame:two");

	@Test
	void publicConstructorRetainsPrivateGraphProvenanceForRealExists() {
		BindingSet original = GraphFrameBindings.supply(input(G2), PRIVATE, G1);
		Filter filter = graphFilter(Set.of(PRIVATE));
		DefaultEvaluationStrategy strategy = strategy();
		QueryValueEvaluationStep condition = strategy.precompile(filter.getCondition(), context());
		try (FilterIterator rows = iterator(filter, original, condition, strategy)) {
			assertThat(rows.hasNext()).isTrue();
			assertThat(rows.next()).isSameAs(original);
			assertThat(rows.hasNext()).isFalse();
		}
	}

	@Test
	void publicConstructorDoesNotRestoreExcludedOrUntrustedPrivateGraph() {
		DefaultEvaluationStrategy strategy = strategy();
		Filter excluded = graphFilter(Set.of());
		BindingSet supplied = GraphFrameBindings.supply(input(G2), PRIVATE, G1);
		try (FilterIterator rows = iterator(excluded, supplied,
				strategy.precompile(excluded.getCondition(), context()), strategy)) {
			assertThat(rows.hasNext()).isFalse();
		}
		QueryBindingSet untrusted = input(G2);
		untrusted.addBinding(PRIVATE, G1);
		Filter retained = graphFilter(Set.of(PRIVATE));
		try (FilterIterator rows = iterator(retained, untrusted,
				strategy.precompile(retained.getCondition(), context()), strategy)) {
			assertThat(rows.hasNext()).isFalse();
		}
	}

	@Test
	void publicConstructorCannotReifyAnExcludedOptimizationParameter() {
		BindingSet observed = observeConditionInput(Set.of());
		assertThat(observed.hasBinding(CALLER)).isFalse();
		BindingSet reified = BindingSetOrigin.materializeParameters(observed,
				List.of(Var.of(CALLER, G1, false, false)), context());
		// Exercise the real parameter materializer and compiled BOUND expression, rather than origin identity alone.
		DefaultEvaluationStrategy strategy = strategy();
		assertThat(strategy.isTrue(strategy.precompile(new Bound(Var.of(CALLER)), context()), reified))
				.as("a condition's excluded name cannot become readable through copied optimizer authority")
				.isFalse();
		assertThat(BindingSetOrigin.of(observed).parameterValue(CALLER)).isNull();
	}

	@Test
	void publicConstructorKeepsAnAbsentPermittedOptimizationParameter() {
		BindingSet observed = observeConditionInput(Set.of(CALLER));
		assertThat(observed.hasBinding(CALLER)).isFalse();
		BindingSet reified = BindingSetOrigin.materializeParameters(observed,
				List.of(Var.of(CALLER, G1, false, false)), context());
		assertThat(reified.getValue(CALLER)).isEqualTo(G1);
		assertThat(BindingSetOrigin.of(observed).parameterValue(CALLER)).isEqualTo(G1);
	}

	private static BindingSet observeConditionInput(Set<String> names) {
		BindingSet original = BindingSetOrigin.optimizationInput(input(G1));
		assertThat(original.isEmpty()).isTrue();
		Filter filter = new Filter(new SingletonSet(), new Bound(Var.of(CALLER)));
		filter.setConditionBindingScope(ConditionBindingScope.retain(names));
		DefaultEvaluationStrategy strategy = strategy();
		QueryValueEvaluationStep bound = strategy.precompile(filter.getCondition(), context());
		AtomicReference<BindingSet> observed = new AtomicReference<>();
		QueryValueEvaluationStep recording = bindings -> {
			observed.set(bindings);
			return bound.evaluate(bindings);
		};
		try (FilterIterator rows = iterator(filter, original, recording, strategy)) {
			assertThat(rows.hasNext()).as("baked optimizer authority does not itself seed the ordinary mapping")
					.isFalse();
		}
		assertThat(observed.get()).isNotNull();
		return observed.get();
	}

	private static Filter graphFilter(Set<String> retained) {
		Filter guard = new Filter(new SingletonSet(), new SameTerm(Var.of(PRIVATE), new ValueConstant(G1)));
		guard.setConditionBindingScope(ConditionBindingScope.ALL);
		Projection projection = new Projection(guard, new ProjectionElemList(), true);
		projection.setProjectionContext(Var.of(CALLER));
		projection.setInheritedGraphParameter(PRIVATE);
		Filter filter = new Filter(new SingletonSet(), new Exists(projection));
		filter.setConditionBindingScope(ConditionBindingScope.retain(retained));
		return filter;
	}

	private static FilterIterator iterator(Filter filter, BindingSet original,
			QueryValueEvaluationStep condition, DefaultEvaluationStrategy strategy) {
		return new FilterIterator(filter, new CloseableIteratorIteration<>(List.of(original).iterator()), condition,
				strategy);
	}

	private static QueryBindingSet input(IRI graph) {
		QueryBindingSet bindings = new QueryBindingSet();
		bindings.addBinding(CALLER, graph);
		return bindings;
	}

	private static QueryEvaluationContext context() {
		return new QueryEvaluationContext.Minimal(null);
	}

	private static DefaultEvaluationStrategy strategy() {
		return new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
	}
}
